import json,catalogue as C
P=json.load(open('probe_final.json')); out=[]
for e in C.C:
    p=P[e['id']]; ok=(p['code']=='200' and p['ct'].startswith('image/') and p['cors']); 
    st=dict(c=p['code'],t=p['ct'],s=p['size'],n=p.get('note',''),ok=ok,w='2026-11-21')
    if e['k']=='l': st=None
    elif e.get('key'): st=dict(ok=None,n='needs your key: not tested',w='2026-11-21')
    elif p['code']=='200' and p['ct'].startswith('image/') and not p['cors']: st['why']='the server answers with an image but sends no CORS header, so the browser cannot use the tiles on the map canvas'
    elif not ok and e['id']=='worldcover': st['why']='no connection to services.terrascope.be from this Mac at test time (curl code 000, also for GetCapabilities)'
    o=dict(src=e.get('src',''),id=e['id'],g=e['g'],k=e['k'],en=e['en'],ar=e['ar'],u=e['u'],a=e['a'],z=e['z'],lic=e['lic'],tx=list(e['tx']),pz=e['pz'],st=st)
    for f in ('time','key','op','cfg'):
        if e.get(f) is not None: o[f]=e[f]
    out.append(o)
G=[['street','Streets and OSM variants','شوارع ونسخ OSM'],['topo','Topographic and terrain','طبوغرافي وتضاريس'],['aerial','Aerial and satellite imagery (incl. history)','صور جوية وأقمار (بتاريخها)'],['satellite','Daily satellite, whole Earth (coarse)','أقمار يومية للأرض كلها (خشنة)'],['thermal','Thermal and heat','حراري وحرارة'],['land','Night lights, vegetation, land cover, water, forest','أضواء الليل والنبات والغطاء الأرضي والمياه والغابات'],['weather','Weather','طقس'],['ref','Reference overlays and infrastructure','طبقات مرجعية وبنية تحتية'],['key','Needs your own key (not tested)','محتاجة مفتاحك (مش مختبرة)'],['links','Viewers and data portals (links, open a new tab)','عارضات ومواقع بيانات (روابط، بتفتح تاب جديد)']]
open('gm_catdata.js','w').write('/* gm_catdata: layer catalogue. Generated by gen_cat.py from catalogue.py + probe_final.json (one real tile per layer fetched with curl on 2026-11-21 from the owner\'s Mac). k: b basemap, o stackable overlay, l link. st: c HTTP code, t content-type, s bytes, ok test result, w date. */\nconst GMC='+json.dumps(out,ensure_ascii=False,separators=(',',':'))+';\nconst GMG='+json.dumps(G,ensure_ascii=False)+';\n')
print(len(out),sum(1 for o in out if o['st'] and o['st'].get('ok')),'ok')
